('12', '0', '2026-08-16 13:29:48', '2026-08-16 10:29:48', '<p>استشاري الأمراض الباطنية بخبرة واسعة في مجاله، يستقبل المرضى في الباطنية.</p>', 'د. خالد المطيري', '', 'publish', 'closed', 'closed', '', '%d8%af-%d8%ae%d8%a7%d9%84%d8%af-%d8%a7%d9%84%d9%85%d8%b7%d9%8a%d8%b1%d9%8a', '', '', '2026-08-16 13:29:48', '2026-08-16 10:29:48', '', '0', 'https://alkhaleejy-group.com/?clinic_doctor=%d8%af-%d8%ae%d8%a7%d9%84%d8%af-%d8%a7%d9%84%d9%85%d8%b7%d9%8a%d8%b1%d9%8a', '0', 'clinic_doctor', '', '0'),
